import type { ArtKey } from '../components/ui/product-art';

export type KitModeKey = 'cook' | 'fix' | 'clean' | 'host';

export interface KitMode {
  label: string;
  art: ArtKey;
  tint: string;
  placeholder: string;
  examples: string[];
  voicePhrase: string;
  people?: boolean;
}

